const PLACEHOLDER_TOKEN = 'replace_with_your_hubspot_private_app_token';
const DEFAULT_HUBSPOT_BASE_URL = 'https://api.hubapi.com';

class ConfigError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ConfigError';
